// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface RollCallSheetOut {
  roster_date: string;
  entries: RollCallEntryOut[];
}

export interface RollCallEntryOut {
  roster_id: number;
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  roster_date: string;
  shift_pattern_id: number;
  shift_name: string;
  start_time: string;
  end_time: string;
  duty_area: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other";
  ward_id: number | null;
  ward_name: string | null;
  department_id: number | null;
  department_name: string | null;
  zone_label: string | null;
  is_on_call: boolean;
  notes: string | null;
  status: "Active" | "Cancelled";
  cancel_reason: string | null;
  /** Taken over from a colleague through this approved duty swap */
  swap_id: number | null;
  row_version: number;
  /** The beds of a ward duty (the nurse's "my beds") */
  bed_ids: number[];
  /** The first arrival punch of the duty (null: not arrived) */
  first_in: string | null;
  first_source: "Badge" | "RollCall" | "Manual" | null;
}

export interface RollCallIn {
  roster_date: string;
  present: Present[];
}

export interface Present {
  employee_id: number;
  /** Arrival time; default now (required for an earlier day's shift). Without a UTC offset it is the hospital's local time */
  at?: string | null;
}

export interface RollCallOut {
  roster_date: string;
  recorded: AttendanceLogOut[];
  /** Staff who had already punched in */
  skipped: RollCallSkippedOut[];
}

/** A punch (badge tap, roll call or manual correction). */
export interface AttendanceLogOut {
  attendance_log_id: number;
  employee_id: number;
  badge_code: string | null;
  station_id: string | null;
  punch_time: string;
  punch_type: "In" | "Out";
  source: "Badge" | "RollCall" | "Manual";
  manual_reason: string | null;
  entered_by: number | null;
  /** The duty date the punch counts for */
  attendance_date: string;
  created_at: string;
}

export interface RollCallSkippedOut {
  employee_id: number;
  full_name: string;
  reason: string;
}

/** Roll-call sheet: who is rostered today and who has arrived — GET /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function rollCallSheet(query?: { roster_date?: string | null; shift_pattern_id?: number | null; ward_id?: number | null }): Promise<RollCallSheetOut> {
  return api<RollCallSheetOut>("GET", withQuery(`/rosters/roll-call`, query), undefined);
}

/** Mark rostered staff present (no badge station) — POST /api/v1/rosters/roll-call (who may call: holders of attendance.roll_call). */
export function takeRollCall(body: RollCallIn): Promise<RollCallOut> {
  return api<RollCallOut>("POST", `/rosters/roll-call`, body, { idempotent: true });
}
